record.field:
# Consolidate memories for all active quests with identities
quests = env['ai.quest'].search([
    ('status', '=', 'active'),
    ('identity_id', '!=', False),
])
consolidated = 0
for quest in quests:
    try:
        count = quest.consolidate_memories()
        consolidated += count
    except Exception:
        pass
_logger = logging.getLogger(__name__)
if consolidated:
    _logger.info('Daily consolidation: %d memories across %d quests', consolidated, len(quests))
